164	    /** The flat amounts asked to be taken off the subtotal, added up; zero when there is no flat discount. */
165	    public BigDecimal getDiscountAmount() {
166	        return discounts.stream().map(InvoiceDiscount::getDiscountAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
167	    }
