169	    /**
170	     * How much one of this invoice's discounts actually takes off the subtotal, to the cent. The
171	     * percentages are taken first, each its share of the subtotal, then the flat amounts in the order
172	     * they were added; none takes off more than is left after those before it.
173	     */
174	    public BigDecimal discountTakenBy(InvoiceDiscount discount) {
175	        BigDecimal subtotal = getSubtotal();
176	        BigDecimal left = subtotal;
177	        for (InvoiceDiscount d : discountsInOrderTaken()) {
178	            BigDecimal wanted = d.isPercentage() ? percentOf(subtotal, d.getDiscountPct()) : d.getDiscountAmount();
179	            BigDecimal taken = wanted.min(left.max(BigDecimal.ZERO.setScale(2)));
180	            if (d == discount) {
181	                return taken;
182	            }
183	            left = left.subtract(taken);
184	        }
185	        return BigDecimal.ZERO.setScale(2);
186	    }
