188	    /** The percentage discounts first, then the flat ones, each in the order they were added. */
189	    private List<InvoiceDiscount> discountsInOrderTaken() {
190	        List<InvoiceDiscount> ordered = new ArrayList<>(discounts.stream().filter(InvoiceDiscount::isPercentage).toList());
191	        ordered.addAll(discounts.stream().filter(d -> !d.isPercentage()).toList());
192	        return ordered;
