195	    /**
196	     * What the line items add up to, before the invoice's discount: the sum of each line after its own
197	     * discount, rounded to the cent.
198	     */
199	    public BigDecimal getSubtotal() {
200	        return lineItems.stream().map(InvoiceLineItem::getAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
201	    }
202	
203	    /** How much the discounts take off the subtotal together (what each takes off, added up), to the cent. */
204	    public BigDecimal getDiscount() {
205	        return discounts.stream().map(this::discountTakenBy).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
206	    }
