213	    /** Whether the prices already include the tax and levy, so they are worked back out rather than added on. */
214	    public boolean isTaxInclusive() {
215	        return taxInclusive;
216	    }
217	
218	    /** Whether the invoice is for a tax-exempt client, so none of its lines are taxed. */
219	    public boolean isTaxExempt() {
220	        return taxExempt;
221	    }
