223	    /**
224	     * What the sales tax is charged on: the taxable lines (leaving out tax-free ones) less the discount
225	     * taken off them, to the cent. On a tax-inclusive invoice that is what is left of them once the tax
226	     * and levy inside them are taken out.
227	     */
228	    public BigDecimal getTaxableBase() {
229	        BigDecimal gross = getDiscountedTaxable();
230	        return taxInclusive ? gross.subtract(getTax()).subtract(getLevy()) : gross;
231	    }
232	
233	    /**
234	     * How much sales tax is added on the taxable base (or is inside it, when tax-inclusive): the tax on
235	     * each taxable line rounded to the cent, added up.
236	     */
237	    public BigDecimal getTax() {
238	        return sumOverTaxableLines(this::taxOn);
239	    }
240	
241	    /** The levy (second tax) percentage added on top of the sales tax; zero when there is no levy. */
242	    public BigDecimal getLevyPct() {
243	        return levyPct;
244	    }
245	
246	    /**
247	     * How much levy is added on the taxable base (or is inside it, when tax-inclusive): the levy on each
248	     * taxable line rounded to the cent, added up.
249	     */
250	    public BigDecimal getLevy() {
251	        return sumOverTaxableLines(this::levyOn);
252	    }
253	
254	    /** The flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
255	    public BigDecimal getSurcharge() {
256	        return surcharge;
257	    }
