259	    /** The taxable lines (leaving out tax-free ones), each less the discount taken off it, added up. */
260	    private BigDecimal getDiscountedTaxable() {
261	        return sumOverTaxableLines(line -> line);
262	    }
263	
264	    /**
265	     * Works a figure out on each taxable line after its discount, to the cent, and adds them up. A
266	     * tax-exempt invoice has no taxable lines.
267	     */
268	    private BigDecimal sumOverTaxableLines(UnaryOperator<BigDecimal> perLine) {
269	        return lineItems.stream().filter(l -> !taxExempt && !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
270	                .map(amount -> perLine.apply(amount.subtract(discountOn(amount))))
271	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
272	    }
273	
274	    /**
275	     * The part of a tax-inclusive price that is the given percentage, worked back out of it: the price
276	     * divided in proportion to the sales tax and levy rates it includes (e.g. 20% tax in 120 is 20).
277	     */
278	    private BigDecimal includedIn(BigDecimal price, BigDecimal pct) {
279	        BigDecimal grossPct = BigDecimal.valueOf(100).add(taxPct).add(levyPct);
280	        return price.multiply(pct).divide(grossPct, 2, RoundingMode.HALF_UP);
281	    }
282	
283	    /** The percentage taken off what is owed when paid early; zero when none is offered. */
284	    public BigDecimal getEarlyPaymentPct() {
285	        return earlyPaymentPct;
286	    }
