302	
303	    /**
304	     * The reduced amount to pay when settling early: the amount less the early-payment percentage of it,
305	     * to the cent; null when no early-payment discount is offered.
306	     */
307	    public BigDecimal getEarlyPaymentAmount() {
308	        return offersEarlyPayment() ? amount.subtract(percentOf(amount, earlyPaymentPct)) : null;
309	    }
310	
311	    public InvoiceStatus getStatus() {
312	        return status;
313	    }
314	
315	    public LocalDate getIssuedDate() {
316	        return issuedDate;
317	    }
318	
319	    public LocalDate getDueDate() {
320	        return dueDate;
321	    }
