503	    public void applyPaidTotal(BigDecimal paid) {
504	        if (status == InvoiceStatus.DRAFT || status == InvoiceStatus.VOID) {
505	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be paid");
