package net.officefloor.hq.app.invoice;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;

/** One discount on an invoice: either a percentage or a flat amount taken off its subtotal, never both. */
@Entity
@Table(name = "invoice_discount")
public class InvoiceDiscount {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "invoice_id", nullable = false)
    private Invoice invoice;

    @Column(name = "discount_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal discountPct = BigDecimal.ZERO.setScale(2);

    @Column(name = "discount_amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal discountAmount = BigDecimal.ZERO.setScale(2);

    protected InvoiceDiscount() {
    }

    InvoiceDiscount(Invoice invoice, BigDecimal discountPct, BigDecimal discountAmount) {
        if (discountPct.signum() != 0 && discountAmount.signum() != 0) {
            throw new IllegalArgumentException("A discount is either a percentage or a flat amount, not both");
        }
        this.invoice = invoice;
        this.discountPct = discountPct.setScale(2, RoundingMode.HALF_UP);
        this.discountAmount = discountAmount.setScale(2, RoundingMode.HALF_UP);
    }

    public Long getId() {
        return id;
    }

    /** The percentage taken off the subtotal; zero when this is a flat discount. */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** The flat amount asked to be taken off the subtotal; zero when this is a percentage discount. */
    public BigDecimal getDiscountAmount() {
        return discountAmount;
    }

    /** Whether this discount is a percentage of the subtotal rather than a flat amount. */
    public boolean isPercentage() {
        return discountPct.signum() > 0;
    }
}
package net.officefloor.hq.app.invoice;

import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;

/**
 * Payload for a discount on a draft invoice: either a percentage taken off or a flat amount taken off
 * (omitted is none), never both. Setting the discount with zero for both removes all discounts.
 */
public record DiscountRequest(
        @NotNull @DecimalMin("0") @DecimalMax("100") @Digits(integer = 3, fraction = 2) BigDecimal discountPct,
        @DecimalMin("0") @Digits(integer = 10, fraction = 2) BigDecimal discountAmount) {

    /** The flat amount taken off, zero when none is given. */
    public BigDecimal flatAmount() {
        return discountAmount == null ? BigDecimal.ZERO : discountAmount;
    }

    /** The discount is a percentage or a flat amount, not both at once. */
    @AssertTrue(message = "A discount is either a percentage or a flat amount, not both")
    public boolean isOneKind() {
        return discountPct == null || discountPct.signum() == 0 || flatAmount().signum() == 0;
    }
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;

/** One discount on an invoice: its percentage or flat amount, and how much it actually takes off. */
public record InvoiceDiscountResponse(Long id, BigDecimal discountPct, BigDecimal discountAmount, BigDecimal amount) {
}
            if (lineItems.isEmpty() && i.get("amount") != null) {
                lineItems = List.of(Map.of("description", InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION,
                        "qty", 1, "unitPrice", i.get("amount")));
            }
            BigDecimal taxPct = i.get("taxPct") == null ? BigDecimal.ZERO
                    : new BigDecimal(i.get("taxPct").toString());
            BigDecimal levyPct = i.get("levyPct") == null ? BigDecimal.ZERO
                    : new BigDecimal(i.get("levyPct").toString());
            // Each line is rounded to the cent first and the rounded lines are added up. A discount takes a
            // percentage off the subtotal; sales tax and a levy each add their percentage of every taxable
            // line after its discount, rounded per line and then added up. The amount is the discounted
            // subtotal plus the tax plus the levy.
            // An invoice for a tax-exempt client carries no tax or levy on any line.
            long projectId = ((Number) i.get("projectId")).longValue();
            Map<String, Object> client = jdbc.queryForMap(
                    "SELECT c.tax_inclusive, c.tax_exempt FROM project p JOIN client c ON c.id = p.client_id WHERE p.id = ?",
                    projectId);
            boolean taxInclusive = Boolean.TRUE.equals(client.get("TAX_INCLUSIVE"));
            boolean taxExempt = Boolean.TRUE.equals(client.get("TAX_EXEMPT"));
            // An invoice may carry several discounts, each a percentage ("pct") or a flat amount ("amount");
            // an older fixture gives at most one as discountPct / discountAmount.
